PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE funcoes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT UNIQUE NOT NULL,
  nome TEXT NOT NULL,
  descricao TEXT,
  categoria TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE setores (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT UNIQUE NOT NULL,
  nome TEXT NOT NULL,
  descricao TEXT,
  responsavel TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE aeronaves (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT UNIQUE NOT NULL,
  modelo TEXT NOT NULL,
  fabricante TEXT,
  prefixo TEXT,
  ano_fabricacao INTEGER,
  status TEXT DEFAULT 'ATIVO',
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE backups (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome_arquivo TEXT NOT NULL,
  tamanho INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, filename TEXT DEFAULT '', size_bytes INTEGER DEFAULT 0, backup_type TEXT DEFAULT 'MANUAL', label TEXT DEFAULT '', storage_path TEXT DEFAULT '');
CREATE TABLE importacoes_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tipo TEXT NOT NULL,
  arquivo_nome TEXT,
  total_registros INTEGER DEFAULT 0,
  sucesso INTEGER DEFAULT 0,
  erros INTEGER DEFAULT 0,
  detalhes TEXT,
  usuario_id INTEGER,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE simuladores (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome TEXT NOT NULL,
  modelo TEXT NOT NULL,
  tipo TEXT NOT NULL,
  fabricante TEXT,
  localizacao TEXT,
  capacidade INTEGER DEFAULT 1,
  status TEXT CHECK(status IN ('ATIVO', 'MANUTENCAO', 'INATIVO')) DEFAULT 'ATIVO',
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE treinamentos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT UNIQUE NOT NULL,
  nome TEXT NOT NULL,
  categoria TEXT NOT NULL,
  descricao TEXT,
  periodicidade INTEGER,
  carga_horaria INTEGER,
  instrutor TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
, total_sessoes INTEGER DEFAULT 1, instrutor_responsavel TEXT, certificacao_relacionada TEXT, status TEXT DEFAULT 'ATIVO', categoria_id INTEGER REFERENCES "qualificacoes_categorias"(id), periodicidade_meses INTEGER);
CREATE TABLE auditoria (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  usuario_id TEXT,
  usuario_nome TEXT,
  acao TEXT NOT NULL,
  tabela_afetada TEXT NOT NULL,
  registro_id TEXT,
  dados_antes TEXT,
  dados_depois TEXT,
  ip_address TEXT,
  user_agent TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE certificado_anexos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  certificado_id INTEGER NOT NULL,
  nome_arquivo TEXT NOT NULL,
  tipo_arquivo TEXT,
  tamanho INTEGER,
  url TEXT NOT NULL,
  uploaded_at TEXT DEFAULT (datetime('now')),
  uploaded_by TEXT,
  FOREIGN KEY (certificado_id) REFERENCES certificados(id)
);
CREATE TABLE user_permissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  usuario_id TEXT NOT NULL,
  permissao TEXT NOT NULL,
  recurso TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (usuario_id) REFERENCES usuarios(id),
  UNIQUE(usuario_id, permissao, recurso)
);
CREATE TABLE user_profiles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  usuario_id TEXT UNIQUE NOT NULL,
  avatar_url TEXT,
  telefone TEXT,
  departamento TEXT,
  cargo TEXT,
  preferencias TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (usuario_id) REFERENCES usuarios(id)
);
CREATE TABLE sessoes_template (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT NOT NULL UNIQUE,
  nome TEXT NOT NULL,
  descricao TEXT,
  treinamento_id INTEGER,
  sessao_numero INTEGER DEFAULT 1,
  total_sessoes INTEGER DEFAULT 1,
  tipo TEXT DEFAULT 'PRATICO', 
  duracao_minutos INTEGER DEFAULT 120,
  ativo BOOLEAN DEFAULT 1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted_at DATETIME
);
CREATE TABLE fichas_sessao (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT UNIQUE NOT NULL,
  agendamento_slot_id INTEGER,
  colaborador_id_aluno INTEGER NOT NULL,
  funcao_na_sessao TEXT DEFAULT 'PF', 
  template_id INTEGER,
  
  
  instrutor_id INTEGER NOT NULL,
  instrutor_codigo_anac TEXT,
  
  
  carga_horaria_total DECIMAL(4,2) DEFAULT 2.0,
  carga_horaria_pf DECIMAL(4,2),
  carga_horaria_pm DECIMAL(4,2),
  
  
  tempo_acumulado DECIMAL(5,2) DEFAULT 0,
  
  
  status TEXT DEFAULT 'PENDENTE', 
  resultado_final TEXT DEFAULT 'PENDENTE',
  nota_final REAL, 
  nota_minima REAL, 
  aprovado BOOLEAN DEFAULT 0,
  
  
  aluno_nome_validado TEXT,
  aluno_matricula_validado TEXT,
  
  
  observacoes TEXT,
  feedback_instrutor TEXT,
  pontos_fortes TEXT,
  pontos_melhoria TEXT,
  
  
  assinado BOOLEAN DEFAULT 0,
  data_assinatura DATETIME,
  hash_assinatura TEXT,
  
  
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted_at DATETIME
, observacoes_gerais TEXT, assinatura_instrutor_completa INTEGER DEFAULT 0, assinatura_aluno_completa INTEGER DEFAULT 0, data_conclusao TEXT, pdf_url TEXT, empresa_id INTEGER, assinatura_instrutor INTEGER DEFAULT 0, assinatura_instrutor_data DATETIME, assinatura_instrutor_usuario_id INTEGER, assinatura_tripulante INTEGER DEFAULT 0, assinatura_tripulante_data DATETIME, assinatura_tripulante_usuario_id INTEGER);
CREATE TABLE catalogo_treinamentos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo TEXT UNIQUE NOT NULL,
    nome TEXT NOT NULL,
    descricao TEXT,
    categoria TEXT, -- 'INICIAL', 'RECORRENTE', 'ESPECIAL'
    carga_horaria INTEGER,
    validade_meses INTEGER,
    observacoes TEXT,
    ativo BOOLEAN DEFAULT 1,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    deleted_at TEXT DEFAULT NULL
, tipo TEXT DEFAULT 'TREINAMENTO');
CREATE TABLE system_config (
    key TEXT PRIMARY KEY,
    value TEXT,
    description TEXT,
    updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE system_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    level TEXT NOT NULL, -- 'INFO', 'WARNING', 'ERROR', 'CRITICAL'
    message TEXT NOT NULL,
    details TEXT, -- JSON
    timestamp TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "qualificacoes_categorias" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome TEXT NOT NULL,
  codigo TEXT NOT NULL UNIQUE,
  descricao TEXT,
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now')),
  deleted_at DATETIME
, cor TEXT DEFAULT '#6B7280', ativo INTEGER DEFAULT 1);
CREATE TABLE tipos_sessao (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT NOT NULL UNIQUE,
  nome TEXT NOT NULL,
  descricao TEXT,
  ativo INTEGER DEFAULT 1,
  ordem INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now')),
  deleted_at DATETIME
);
CREATE TABLE IF NOT EXISTS "modelos_sessao" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT NOT NULL UNIQUE,
  nome TEXT NOT NULL,
  tipo TEXT,
  descricao TEXT,
  duracao_estimada INTEGER,
  treinamento_id TEXT,
  ordem_no_treinamento INTEGER,
  ativo BOOLEAN DEFAULT 1,
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now')),
  deleted_at DATETIME NULL
);
CREATE TABLE IF NOT EXISTS "manobras_categorias" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT NOT NULL UNIQUE,
  nome TEXT NOT NULL,
  tipo TEXT DEFAULT 'NORMAL',
  ordem INTEGER DEFAULT 0,
  cor TEXT DEFAULT '#3B82F6',
  created_at DATETIME DEFAULT (datetime('now')),
  updated_at DATETIME DEFAULT (datetime('now')),
  deleted_at DATETIME
);
CREATE TABLE audit_cascade (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  modelo TEXT NOT NULL, 
  arquivo TEXT, 
  comando TEXT, 
  tempo_ms INTEGER, 
  sucesso INTEGER DEFAULT 1, 
  checksum TEXT, 
  erros INTEGER DEFAULT 0, 
  warnings INTEGER DEFAULT 0, 
  score REAL, 
  detalhes TEXT, 
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE empresas (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome TEXT NOT NULL UNIQUE,
  razao_social TEXT,
  cnpj TEXT UNIQUE,
  logo_url TEXT,
  logo_hash TEXT,
  assinatura_diretor_url TEXT,
  assinatura_diretor_hash TEXT,
  assinatura_diretor_nome TEXT DEFAULT 'Diretor Geral',
  telefone TEXT,
  email TEXT,
  endereco TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE certificados (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  habilitacao_id INTEGER NOT NULL,
  funcionario_id INTEGER NOT NULL,
  qualificacao_id INTEGER NOT NULL,
  arquivo_url TEXT NOT NULL,
  arquivo_nome TEXT NOT NULL,
  arquivo_tamanho INTEGER,
  arquivo_hash TEXT,
  numero_certificado TEXT UNIQUE NOT NULL,
  tipo TEXT DEFAULT 'upload',
  data_emissao DATE,
  data_vencimento DATE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted_at DATETIME
);
CREATE TABLE empresa_certificado_config (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  empresa_id INTEGER NOT NULL,
  template_html TEXT NOT NULL DEFAULT '',
  logo_r2_url TEXT,
  logo_filename TEXT,
  cor_primaria TEXT NOT NULL DEFAULT '#0066cc',
  cor_secundaria TEXT NOT NULL DEFAULT '#333333',
  criado_em DATETIME DEFAULT CURRENT_TIMESTAMP,
  atualizado_em DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE empresa_config (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  empresa_id INTEGER NOT NULL UNIQUE,
  
  
  nome TEXT NOT NULL,
  logo_url TEXT,
  
  
  template_certificado TEXT,
  cor_primaria TEXT DEFAULT '#0066cc',
  cor_secundaria TEXT DEFAULT '#333333',
  
  
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted_at DATETIME,
  
  
  FOREIGN KEY (empresa_id) REFERENCES empresas(id)
);
CREATE TABLE schema_versions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  version TEXT NOT NULL,
  module TEXT NOT NULL,
  description TEXT,
  applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
ANALYZE sqlite_schema;
CREATE TABLE IF NOT EXISTS "manobras_avaliacoes" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT UNIQUE NOT NULL,
  ficha_id INTEGER NOT NULL,
  manobra_id INTEGER NOT NULL,
  nota REAL DEFAULT 0,
  observacoes TEXT,
  feedback_instrutor TEXT,
  executada INTEGER DEFAULT 0,
  avaliador_id INTEGER,
  
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);
CREATE TABLE sessoes_participantes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT UNIQUE NOT NULL,
  sessao_id INTEGER NOT NULL,
  funcionario_id INTEGER NOT NULL,
  funcao TEXT, -- PF (Pilot Flying), PM (Pilot Monitoring), PIC, SIC, etc
  status TEXT DEFAULT 'CONFIRMADO', -- CONFIRMADO, FALTOU, DISPENSADO
  ciclo_executado INTEGER DEFAULT 1,
  
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);
CREATE TABLE sessoes_manobras (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT UNIQUE NOT NULL,
  sessao_id INTEGER NOT NULL,
  manobra_id INTEGER NOT NULL,
  ordem INTEGER,
  status TEXT DEFAULT 'PENDENTE', -- PENDENTE, CONCLUIDA, AJUSTE_NECESSARIO
  
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "simulador_agendamentos" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT UNIQUE NOT NULL,
  simulador_id INTEGER NOT NULL,
  funcionario_id INTEGER NOT NULL,
  instrutor_id INTEGER NOT NULL,
  checador_id INTEGER,
  template_id INTEGER,
  data DATE NOT NULL,
  hora_inicio TIME NOT NULL,
  hora_fim TIME NOT NULL,
  duracao_minutos INTEGER,
  status TEXT DEFAULT 'AGENDADO', -- AGENDADO, EM_ANDAMENTO, CONCLUIDO, CANCELADO
  tipo_sessao TEXT, -- INICIAL, RECORRENTE, CHECK, PF, PM
  observacoes TEXT,
  
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);
CREATE TABLE migracao_mapeamento_ids (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tabela TEXT NOT NULL,
  id_v1 INTEGER NOT NULL,
  id_v2 INTEGER NOT NULL,
  criado_em DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(tabela, id_v1)
);
CREATE TABLE papeis (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Dados básicos
  nome TEXT NOT NULL UNIQUE,  -- PILOTO, INSTRUTOR, SUPERVISOR, RH_ADMIN, MECANICO
  descricao TEXT,
  
  -- Permissões (JSON string)
  -- Exemplo: '[{"recurso":"qualificacoes","acao":"criar"},{"recurso":"pessoas","acao":"editar"}]'
  permissoes TEXT NOT NULL DEFAULT '[]',
  
  -- Status
  ativo INTEGER NOT NULL DEFAULT 1,
  
  -- Auditoria
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE pessoas_papeis (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Relações
  pessoa_id INTEGER NOT NULL,
  papel_id INTEGER NOT NULL,
  
  -- Vigência
  data_inicio TEXT NOT NULL DEFAULT (datetime('now')),
  data_fim TEXT,  -- NULL = ainda ativo
  
  -- Auditoria
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT,
  
  -- Constraints
  FOREIGN KEY (pessoa_id) REFERENCES "__backup_pessoas"(id) ON DELETE CASCADE,
  FOREIGN KEY (papel_id) REFERENCES papeis(id) ON DELETE CASCADE,
  UNIQUE (pessoa_id, papel_id)
);
CREATE TABLE credenciais (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Relação
  pessoa_id INTEGER NOT NULL,
  
  -- Tipo de credencial
  tipo TEXT NOT NULL,  -- CPF, CNH, RG, LICENSE_AVIADOR, PASSPORT, OTHER
  
  -- Dados da credencial
  numero TEXT NOT NULL UNIQUE,
  data_emissao TEXT,
  data_validade TEXT,  -- NULL = sem vencimento
  orgao_expedidor TEXT,
  
  -- Status
  status TEXT NOT NULL DEFAULT 'ATIVO',  -- ATIVO, EXPIRADO, REVOGADO
  
  -- Auditoria
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT,
  
  -- Constraints
  FOREIGN KEY (pessoa_id) REFERENCES "__backup_pessoas"(id) ON DELETE CASCADE,
  CONSTRAINT check_tipo_valid CHECK (tipo IN ('CPF', 'CNH', 'RG', 'LICENSE_AVIADOR', 'PASSPORT', 'OTHER')),
  CONSTRAINT check_status_valid CHECK (status IN ('ATIVO', 'EXPIRADO', 'REVOGADO'))
);
CREATE TABLE pessoas_auditoria_acessos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Dados do acesso
  pessoa_id INTEGER NOT NULL,
  usuario_id TEXT NOT NULL,  -- Quem acessou
  acao TEXT NOT NULL,  -- 'VISUALIZAR', 'BUSCAR_CPF', 'EDITAR', 'DELETAR'
  recurso TEXT NOT NULL,  -- 'pessoas', 'credenciais', etc.
  dados_sensíveis TEXT,  -- JSON com campos acessados (ex: {"cpf": true, "email": true})
  
  -- Contexto
  ip_origem TEXT,
  user_agent TEXT,
  motivo TEXT,  -- Opcional: justificativa do acesso
  
  -- Timestamp
  acessado_em TEXT NOT NULL DEFAULT (datetime('now')),
  
  -- Constraints
  FOREIGN KEY (pessoa_id) REFERENCES "__backup_pessoas"(id) ON DELETE CASCADE
);
CREATE TABLE certificados_templates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  empresa_id INTEGER NOT NULL,
  
  -- Identificação
  nome VARCHAR(100) NOT NULL,
  descricao TEXT,
  tipo VARCHAR(50) DEFAULT 'PADRAO', -- PADRAO, TREINAMENTO, CURSO, CUSTOM
  
  -- Layout (JSON com estrutura do template)
  template_json TEXT NOT NULL,
  
  -- Assets (URLs no R2)
  logo_url TEXT,
  background_url TEXT,
  assinatura_url TEXT, -- Assinatura digital do responsável
  
  -- Configurações de estilo
  fonte VARCHAR(50) DEFAULT 'Arial',
  tamanho_fonte_titulo INTEGER DEFAULT 24,
  tamanho_fonte_corpo INTEGER DEFAULT 14,
  cor_primaria VARCHAR(7) DEFAULT '#000000', -- Título
  cor_secundaria VARCHAR(7) DEFAULT '#666666', -- Corpo
  cor_destaque VARCHAR(7) DEFAULT '#0066CC', -- Nome pessoa
  
  -- Layout
  orientacao VARCHAR(20) DEFAULT 'landscape', -- landscape, portrait
  tamanho_papel VARCHAR(10) DEFAULT 'A4', -- A4, Letter
  margem_cm DECIMAL(4,2) DEFAULT 2.0,
  
  -- Status
  ativo BOOLEAN DEFAULT 1,
  padrao BOOLEAN DEFAULT 0, -- Template padrão da empresa
  
  -- Metadados
  versao VARCHAR(10) DEFAULT '1.0',
  tags TEXT, -- Separado por vírgula: "treinamento,aviacao,basico"
  
  -- Auditoria
  created_by INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_by INTEGER,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted_at DATETIME,
  
  FOREIGN KEY (empresa_id) REFERENCES empresas(id),
  FOREIGN KEY (created_by) REFERENCES "__backup_pessoas"(id),
  FOREIGN KEY (updated_by) REFERENCES "__backup_pessoas"(id)
);
CREATE TABLE job_queue (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tipo TEXT NOT NULL CHECK(tipo IN ('GERAR_CERTIFICADO', 'PROCESSAR_RENOVACAO', 'ENVIAR_NOTIFICACAO')),
  payload TEXT NOT NULL, -- JSON com dados do job
  status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING', 'PROCESSING', 'DONE', 'FAILED')),
  tentativas INTEGER NOT NULL DEFAULT 0,
  max_tentativas INTEGER NOT NULL DEFAULT 3,
  erro TEXT, -- Mensagem de erro se falhar
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  processado_em TIMESTAMP,
  concluido_em TIMESTAMP,
  
  -- Índices para performance
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP,
  deleted_at TIMESTAMP
);
CREATE TABLE job_execution_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  job_id INTEGER NOT NULL,
  status TEXT NOT NULL,
  mensagem TEXT,
  detalhes TEXT, -- JSON com detalhes
  executado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  
  FOREIGN KEY (job_id) REFERENCES job_queue(id) ON DELETE CASCADE
);
CREATE TABLE migracao_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tabela_origem TEXT NOT NULL,
  tabela_destino TEXT NOT NULL,
  acao TEXT NOT NULL,
  registros_afetados INTEGER DEFAULT 0,
  detalhes TEXT,
  status TEXT DEFAULT 'PENDENTE',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sessoes (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  descricao TEXT,
  data_inicio TEXT,
  data_fim TEXT,
  duracao_minutos INTEGER,
  tipo TEXT DEFAULT 'SIMULADOR', -- 'SIMULADOR', 'TREINAMENTO', 'TEMPLATE'
  status TEXT DEFAULT 'AGENDADA', -- 'AGENDADA', 'EM_PROGRESSO', 'CONCLUIDA', 'CANCELADA'
  instrutor_id INTEGER,
  migrado_de TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, carga_horaria INTEGER, hora_diurna INTEGER, hora_noturna INTEGER, pouso_diurno INTEGER, pouso_noturno INTEGER, deleted_at TEXT DEFAULT NULL,
  FOREIGN KEY (instrutor_id) REFERENCES usuarios(id)
);
CREATE TABLE IF NOT EXISTS "sessoes_fichas" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT UNIQUE NOT NULL,
  agendamento_id TEXT,
  colaborador_id TEXT,
  instrutor_id TEXT,
  template_id TEXT,
  status TEXT DEFAULT 'RASCUNHO',
  nota_media REAL,
  resultado_final TEXT,
  carga_horaria INTEGER,
  hora_diurna INTEGER,
  hora_noturna INTEGER,
  pouso_diurno INTEGER,
  pouso_noturno INTEGER,
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  updated_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now'))
);
CREATE TABLE IF NOT EXISTS "manobras" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  codigo TEXT UNIQUE NOT NULL,
  nome TEXT NOT NULL,
  categoria TEXT,
  descricao TEXT,
  nivel_dificuldade INTEGER,
  tempo_estimado INTEGER,
  pontuacao_minima REAL,
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  updated_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  deleted_at TEXT DEFAULT NULL
);
CREATE TABLE sessao_manobras (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  modelo_id INTEGER NOT NULL,
  manobra_id INTEGER NOT NULL,
  ordem INTEGER,
  obrigatoria BOOLEAN DEFAULT 0,
  observacoes TEXT,
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  updated_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now'))
);
CREATE TABLE IF NOT EXISTS "template_manobras" ( id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NOT NULL, manobra_id INTEGER NOT NULL, ordem INTEGER DEFAULT 1, obrigatoria BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, tempo_estimado_min INTEGER DEFAULT 10, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY (template_id) REFERENCES sessoes_template(id), FOREIGN KEY (manobra_id) REFERENCES manobras(id), UNIQUE(template_id, manobra_id) );
CREATE TABLE IF NOT EXISTS "ficha_manobras_avaliacao" ( id INTEGER PRIMARY KEY AUTOINCREMENT, ficha_id INTEGER NOT NULL, manobra_id INTEGER NOT NULL, nota REAL DEFAULT 0, observacoes TEXT, executada BOOLEAN DEFAULT 0, data_execucao DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (ficha_id) REFERENCES fichas_sessao(id), FOREIGN KEY (manobra_id) REFERENCES manobras(id), UNIQUE(ficha_id, manobra_id) );
CREATE TABLE IF NOT EXISTS "fichas_manobras_historico" ( id INTEGER PRIMARY KEY AUTOINCREMENT, ficha_uuid TEXT NOT NULL, participante_id INTEGER NOT NULL, manobra_id INTEGER NOT NULL, manobra_codigo TEXT NOT NULL, manobra_nome TEXT NOT NULL, nota_atual REAL NOT NULL CHECK(nota_atual >= 0 AND nota_atual <= 10), observacoes TEXT, avaliador_id INTEGER NOT NULL, data_avaliacao TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, FOREIGN KEY (ficha_uuid) REFERENCES fichas_sessao(uuid) ON DELETE CASCADE, FOREIGN KEY (participante_id) REFERENCES "funcionarios_old"(id) ON DELETE CASCADE, FOREIGN KEY (manobra_id) REFERENCES manobras(id) ON DELETE CASCADE, FOREIGN KEY (avaliador_id) REFERENCES "funcionarios_old"(id) ON DELETE CASCADE );
CREATE TABLE pasta_virtual ( id INTEGER PRIMARY KEY AUTOINCREMENT, funcionario_id INTEGER NOT NULL, tipo_documento TEXT NOT NULL, categoria TEXT, caminho_arquivo TEXT, arquivourl TEXT, nome_arquivo TEXT, nomeoriginal TEXT, arquivo_tamanho INTEGER, tamanho INTEGER, dataupload TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), uploadedby INTEGER, certificacao_id INTEGER, descricao TEXT, deleted_at TEXT, FOREIGN KEY(funcionario_id) REFERENCES "funcionarios_old"(id) );
CREATE TABLE IF NOT EXISTS "alertas_enviados" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tipo TEXT NOT NULL,
    funcionario_id INTEGER NOT NULL,
    qualificacao_id INTEGER,
    data_envio TEXT DEFAULT (datetime('now')),
    destinatario TEXT,
    status TEXT DEFAULT 'ENVIADO',
    FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id),
    FOREIGN KEY (qualificacao_id) REFERENCES qualificacoes_registros(id)
);
CREATE TABLE IF NOT EXISTS "arquivos" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  nome_original TEXT NOT NULL,
  nome_arquivo TEXT NOT NULL,
  categoria TEXT DEFAULT 'geral',
  tamanho INTEGER,
  tipo TEXT,
  url_r2 TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT,
  deleted_at TEXT,
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE IF NOT EXISTS "compliance_status" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  data_avaliacao TEXT NOT NULL,
  status TEXT CHECK(status IN ('COMPLIANT', 'NON_COMPLIANT', 'PENDING')) NOT NULL,
  detalhes TEXT,
  avaliado_por TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE IF NOT EXISTS "consentimentos_lgpd" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  tipo TEXT NOT NULL CHECK(tipo IN ('coleta_dados', 'uso_imagem', 'compartilhamento', 'tratamento_dados')),
  aceito INTEGER NOT NULL DEFAULT 0,
  data_aceite TEXT,
  ip_aceite TEXT,
  user_agent TEXT,
  revogado INTEGER DEFAULT 0,
  data_revogacao TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE IF NOT EXISTS "funcionario_documentos" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  tipo_documento TEXT NOT NULL,
  nome_arquivo TEXT NOT NULL,
  caminho_r2 TEXT NOT NULL,
  tamanho_bytes INTEGER NOT NULL,
  mime_type TEXT NOT NULL,
  descricao TEXT,
  data_upload DATETIME DEFAULT CURRENT_TIMESTAMP,
  uploaded_by TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  deleted_at DATETIME,
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE IF NOT EXISTS "funcionarios_aeronaves" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  aeronave_id INTEGER NOT NULL,
  data_inicio TEXT NOT NULL,
  data_fim TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id),
  FOREIGN KEY (aeronave_id) REFERENCES aeronaves(id),
  UNIQUE(funcionario_id, aeronave_id, data_inicio)
);
CREATE TABLE IF NOT EXISTS "logs_acesso_dados" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  usuario_id INTEGER,
  acao TEXT NOT NULL CHECK(acao IN ('READ', 'UPDATE', 'DELETE', 'EXPORT')),
  campos_acessados TEXT,
  ip TEXT,
  user_agent TEXT,
  timestamp TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE IF NOT EXISTS "notificacoes" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tipo TEXT NOT NULL,
    titulo TEXT NOT NULL,
    mensagem TEXT NOT NULL,
    funcionario_id INTEGER,
    lida BOOLEAN DEFAULT 0,
    data_envio TEXT DEFAULT (datetime('now')),
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE refresh_tokens (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  token TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now')),
  revoked_at TEXT,
  FOREIGN KEY (user_id) REFERENCES usuarios(id)
);
CREATE TABLE legacy_funcionarios (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Dados do funcionário
  matricula TEXT UNIQUE NOT NULL,
  nome TEXT NOT NULL,
  cpf TEXT,
  funcao TEXT,
  setor TEXT,
  email TEXT,
  telefone TEXT,
  
  -- Dados legados de qualificações (denormalizados)
  cma_numero TEXT,
  cma_data_vencimento DATE,
  cma_status TEXT,
  aso_data_vencimento DATE,
  nivel_icao TEXT,
  nivel_icao_data_vencimento DATE,
  
  -- Metadata de origem
  origem TEXT DEFAULT 'LEGACY_IMPORT',
  fonte_backup TEXT, -- qual arquivo/commit originou
  
  -- Auditoria
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  imported_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now'))
);
CREATE TABLE legacy_qualificacoes_tipos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Identificadores
  codigo TEXT UNIQUE NOT NULL,
  nome TEXT NOT NULL,
  
  -- Metadados
  categoria TEXT CHECK (categoria IN ('TREINAMENTO', 'EXAME', 'CHECK')),
  validade_meses INTEGER,
  periodicidade_meses INTEGER,
  carga_horaria INTEGER,
  descricao TEXT,
  nota_minima REAL,
  
  -- Origem
  origem TEXT DEFAULT 'LEGACY_IMPORT',
  fonte_backup TEXT,
  
  -- Auditoria
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  imported_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now'))
);
CREATE TABLE legacy_qualificacoes_historico (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Relacionamentos (por enquanto como TEXT, para aceitar qualquer formato)
  matricula TEXT NOT NULL,
  codigo TEXT NOT NULL,
  
  -- Dados denormalizados (podem vir nos dumps legados)
  funcionario_nome TEXT,
  qualificacao_nome TEXT,
  
  -- Categoria e tipo
  categoria TEXT CHECK (categoria IN ('TREINAMENTO', 'EXAME', 'CHECK')),
  tipo TEXT,
  
  -- Datas
  data_conclusao DATE,
  data_vencimento DATE,
  validade DATE,
  data_execucao DATE, -- nome antigo, pode ser mapeado para data_conclusao
  
  -- Avaliação
  nota INTEGER,
  nota_final REAL,
  resultado TEXT,
  
  -- Status
  status TEXT,
  
  -- Outros campos legados
  instrutor TEXT,
  checador TEXT,
  local TEXT,
  observacoes TEXT,
  carga_horaria INTEGER,
  
  -- Certificado
  certificado_url TEXT,
  certificado_numero TEXT,
  
  -- Origem
  origem TEXT DEFAULT 'LEGACY_IMPORT',
  fonte_backup TEXT,
  
  -- Auditoria
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  imported_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now'))
);
CREATE TABLE legacy_import_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  -- Identificação da importação
  batch_id TEXT NOT NULL,
  fonte TEXT NOT NULL, -- arquivo, commit, backup
  tabela_destino TEXT NOT NULL, -- legacy_funcionarios, legacy_qualificacoes_tipos, etc.
  
  -- Estatísticas
  total_linhas INTEGER DEFAULT 0,
  linhas_importadas INTEGER DEFAULT 0,
  linhas_duplicadas INTEGER DEFAULT 0,
  linhas_erro INTEGER DEFAULT 0,
  
  -- Status
  status TEXT CHECK (status IN ('INICIADO', 'CONCLUIDO', 'ERRO', 'ROLLBACK')),
  erro_mensagem TEXT,
  
  -- Auditoria
  started_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  finished_at TEXT,
  
  -- Usuário responsável
  imported_by TEXT DEFAULT 'SYSTEM'
);
CREATE TABLE documentos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT NOT NULL UNIQUE,
  funcionario_id INTEGER NOT NULL,
  nome_arquivo TEXT NOT NULL,
  tipo TEXT NOT NULL, -- MIME type (application/pdf, image/png, etc)
  tamanho INTEGER NOT NULL, -- bytes
  r2_key TEXT NOT NULL UNIQUE, -- Chave no bucket R2
  descricao TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT DEFAULT NULL,
  
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE licencas (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id TEXT NOT NULL,
  tipo TEXT NOT NULL,               -- 'CMA', 'CANAC', 'CHT', 'PP', 'PC', 'PLA', 'IFR', 'INVA', etc.
  numero TEXT NOT NULL,
  data_emissao TEXT NOT NULL,       -- ISO8601 'YYYY-MM-DD'
  data_vencimento TEXT NOT NULL,    -- ISO8601 'YYYY-MM-DD'
  observacoes TEXT,
  
  -- Auditoria
  created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  updated_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%S', 'now')),
  deleted_at TEXT DEFAULT NULL,
  
  FOREIGN KEY (funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE cadastro_manobras (id INTEGER PRIMARY KEY AUTOINCREMENT, tipo_sessao TEXT NOT NULL, tipo_aeronave TEXT NOT NULL, codigo TEXT, descricao TEXT NOT NULL, categoria TEXT, ordem INTEGER, obrigatoria INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT);
CREATE TABLE instrutores_simulador (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id TEXT NOT NULL,
  habilitacoes TEXT,
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT,
  FOREIGN KEY(funcionario_id) REFERENCES "funcionarios_old"(id)
);
CREATE TABLE fichas_sessao_manobras (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ficha_id INTEGER NOT NULL,
  codigo TEXT NOT NULL,
  descricao TEXT,
  categoria TEXT,
  ordem INTEGER DEFAULT 0,
  resultado TEXT DEFAULT 'NAO_REALIZADA',
  observacoes TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY(ficha_id) REFERENCES fichas_sessao(id)
);
CREATE TABLE habilitacoes_funcionarios (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  habilitacao_id INTEGER NOT NULL,
  data_obtencao TEXT,
  vencimento TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT,
  FOREIGN KEY(funcionario_id) REFERENCES "funcionarios_old"(id),
  FOREIGN KEY(habilitacao_id) REFERENCES habilitacoes(id),
  UNIQUE(funcionario_id, habilitacao_id)
);
CREATE TABLE qualificacoes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ficha_sessao_id INTEGER NOT NULL,
  qualificacao_tipo_id INTEGER NOT NULL,
  data_obtencao TEXT,
  validade_ate TEXT,
  status TEXT DEFAULT 'OBTIDA',
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT,
  FOREIGN KEY(ficha_sessao_id) REFERENCES fichas_sessao(id),
  FOREIGN KEY(qualificacao_tipo_id) REFERENCES qualificacoes_tipos(id)
);
CREATE TABLE auditoria_avancada_v2 (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          tabela TEXT NOT NULL,
          acao TEXT NOT NULL,
          registro_id TEXT NOT NULL,
          dados_anteriores TEXT,
            dados_novos TEXT,
          created_at TEXT NOT NULL DEFAULT (datetime('now'))
        , usuario_id INTEGER, ip_address TEXT, user_agent TEXT, origem TEXT DEFAULT 'system');
CREATE TABLE qualificacoes_historico_stats_daily (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  day DATE NOT NULL, 
  scope_hash TEXT NOT NULL, 
  total INTEGER NOT NULL DEFAULT 0,
  validas INTEGER NOT NULL DEFAULT 0,
  vencendo INTEGER NOT NULL DEFAULT 0,
  vencidas INTEGER NOT NULL DEFAULT 0,
  renovadas INTEGER NOT NULL DEFAULT 0,
  generated_at DATETIME NOT NULL DEFAULT (datetime('now')),
  UNIQUE(day, scope_hash)
);
CREATE TABLE IF NOT EXISTS "qualificacoes_tipos" (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  codigo TEXT NOT NULL,
  categoria TEXT NOT NULL,
  validade_meses INTEGER,
  descricao TEXT,
  ativo INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT
);
CREATE TABLE funcionarios (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	nome TEXT NOT NULL,
	email TEXT UNIQUE,
	matricula TEXT UNIQUE,
	cpf TEXT,
	cargo TEXT,
	departamento TEXT,
	status TEXT DEFAULT 'ATIVO',
	observacoes TEXT,
	nome_guerra TEXT,
	funcao TEXT,
	setor TEXT,
	codigo_anac TEXT,
	is_instrutor INTEGER DEFAULT 0,
	is_checador INTEGER DEFAULT 0,
	ativo INTEGER DEFAULT 1,
	-- Campos adicionais de perfil
	rg TEXT,
	data_nascimento TEXT,
	sexo TEXT,
	nacionalidade TEXT,
	telefone_emergencia TEXT,
	contato_emergencia_nome TEXT,
	foto_url TEXT,
	base TEXT,
	aeronave TEXT,
	data_admissao TEXT,
	nivel_icao TEXT,
	validade_icao TEXT,
	cma TEXT,
	validade_cma TEXT,
	aso TEXT,
	validade_aso TEXT,
	sispat TEXT,
	prestserv TEXT,
	-- Endereço detalhado
	endereco TEXT,
	cep TEXT,
	logradouro TEXT,
	numero TEXT,
	complemento TEXT,
	bairro TEXT,
	cidade TEXT,
	estado TEXT,
	escala TEXT,
	-- Auditoria
	created_at TEXT DEFAULT (datetime('now')),
	updated_at TEXT DEFAULT (datetime('now')),
	deleted_at TEXT
, telefone TEXT);
CREATE TABLE hospedagens (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  hotel TEXT NOT NULL,
  quarto TEXT,
  data_checkin TEXT NOT NULL,
  data_checkout TEXT NOT NULL,
  valor REAL NOT NULL,
  status TEXT CHECK(status IN ('reservado', 'confirmado', 'cancelado', 'finalizado')) DEFAULT 'reservado',
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT,
  FOREIGN KEY (funcionario_id) REFERENCES funcionarios(id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE registros_frms (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  data_registro TEXT NOT NULL,
  horas_sono REAL NOT NULL CHECK(horas_sono >= 0 AND horas_sono <= 24),
  nivel_fadiga INTEGER CHECK(nivel_fadiga BETWEEN 1 AND 10) NOT NULL,
  sintomas TEXT,
  apto_voo INTEGER DEFAULT 1,
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT,
  FOREIGN KEY (funcionario_id) REFERENCES funcionarios(id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "_backup_qh_tmp" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  qualificacao_id INTEGER,
  tipo_codigo TEXT,
  codigo TEXT,
  categoria TEXT,
  validade TEXT,
  numero_certificado TEXT,
  orgao_emissor TEXT,
  observacoes TEXT,
  arquivo_url TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  deleted_at TEXT,
  FOREIGN KEY(funcionario_id) REFERENCES funcionarios(id) ON DELETE RESTRICT
);
CREATE TABLE _backup_qualificacoes_historico(
  id INT,
  funcionario_id INT,
  qualificacao_id INT,
  tipo_codigo TEXT,
  codigo TEXT,
  categoria TEXT,
  validade TEXT,
  numero_certificado TEXT,
  orgao_emissor TEXT,
  observacoes TEXT,
  arquivo_url TEXT,
  created_at TEXT,
  updated_at TEXT,
  deleted_at TEXT
);
CREATE TABLE _backup_qualificacoes_tipos(
  id TEXT,
  nome TEXT,
  codigo TEXT,
  categoria TEXT,
  validade_meses INT,
  descricao TEXT,
  ativo INT,
  created_at TEXT,
  updated_at TEXT,
  deleted_at TEXT
);
CREATE TABLE _backup_funcionarios(
  id INT,
  nome TEXT,
  email TEXT,
  matricula TEXT,
  cpf TEXT,
  cargo TEXT,
  departamento TEXT,
  status TEXT,
  observacoes TEXT,
  nome_guerra TEXT,
  funcao TEXT,
  setor TEXT,
  codigo_anac TEXT,
  is_instrutor INT,
  is_checador INT,
  ativo INT,
  rg TEXT,
  data_nascimento TEXT,
  sexo TEXT,
  nacionalidade TEXT,
  telefone_emergencia TEXT,
  contato_emergencia_nome TEXT,
  foto_url TEXT,
  base TEXT,
  aeronave TEXT,
  data_admissao TEXT,
  nivel_icao TEXT,
  validade_icao TEXT,
  cma TEXT,
  validade_cma TEXT,
  aso TEXT,
  validade_aso TEXT,
  sispat TEXT,
  prestserv TEXT,
  endereco TEXT,
  cep TEXT,
  logradouro TEXT,
  numero TEXT,
  complemento TEXT,
  bairro TEXT,
  cidade TEXT,
  estado TEXT,
  escala TEXT,
  created_at TEXT,
  updated_at TEXT,
  deleted_at TEXT,
  telefone TEXT
);
CREATE TABLE _qualificacoes_mapping(
  historico_id INT,
  tipo_codigo TEXT,
  codigo TEXT,
  qualificacao_tipo_id TEXT,
  status
);
CREATE TABLE _qualificacoes_enriquecimento (historico_id INTEGER PRIMARY KEY, categoria TEXT, validade TEXT, numero_certificado TEXT, orgao_emissor TEXT, sugestao_codigo TEXT, sugestao_nome TEXT, status TEXT DEFAULT 'PENDING', created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE qualificacoes_historico (id INTEGER PRIMARY KEY AUTOINCREMENT, funcionario_id INTEGER NOT NULL, qualificacao_id INTEGER NOT NULL, tipo_codigo TEXT, codigo TEXT, categoria TEXT, validade TEXT, numero_certificado TEXT, observacoes TEXT, arquivo_url TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), deleted_at TEXT, FOREIGN KEY(funcionario_id) REFERENCES funcionarios(id) ON DELETE RESTRICT, FOREIGN KEY(qualificacao_id) REFERENCES qualificacoes_tipos(id) ON DELETE RESTRICT);
CREATE TABLE usuarios (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  nome TEXT NOT NULL,
  perfil TEXT DEFAULT 'USUARIO' CHECK(perfil IN ('ADMIN', 'COMPLIANCE', 'GESTOR', 'USUARIO')),
  funcionario_id INTEGER,
  deleted_at INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  active INTEGER DEFAULT 1,
  last_login TEXT,
  failed_login_attempts INTEGER DEFAULT 0,
  locked_until TEXT,
  FOREIGN KEY (funcionario_id) REFERENCES funcionarios(id)
);
CREATE TABLE sessoes_treinamento (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  treinamento_id INTEGER NOT NULL,
  funcionario_id INTEGER NOT NULL,
  data_inicio TEXT NOT NULL,
  data_conclusao TEXT,
  status TEXT CHECK(status IN ('AGENDADO','EM_ANDAMENTO','CONCLUIDO','CANCELADO')) DEFAULT 'AGENDADO',
  nota_final REAL,
  aprovado INTEGER,
  observacoes TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (treinamento_id) REFERENCES treinamentos(id),
  FOREIGN KEY (funcionario_id) REFERENCES funcionarios(id)
);
CREATE TABLE solicitacoes_lgpd (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  funcionario_id INTEGER NOT NULL,
  tipo TEXT NOT NULL CHECK(tipo IN ('confirmacao_dados','acesso_dados','correcao_dados','anonimizacao','eliminacao','portabilidade','informacao_compartilhamento','revogacao_consentimento')),
  status TEXT NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','EM_ANDAMENTO','CONCLUIDA','REJEITADA')),
  descricao TEXT,
  data_solicitacao TEXT DEFAULT (datetime('now')),
  data_conclusao TEXT,
  responsavel_id INTEGER,
  observacoes TEXT,
  FOREIGN KEY (funcionario_id) REFERENCES funcionarios(id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_funcoes_codigo ON funcoes(codigo) WHERE deleted_at IS NULL;
CREATE INDEX idx_funcoes_ativo ON funcoes(ativo) WHERE deleted_at IS NULL;
CREATE INDEX idx_setores_codigo ON setores(codigo) WHERE deleted_at IS NULL;
CREATE INDEX idx_setores_ativo ON setores(ativo) WHERE deleted_at IS NULL;
CREATE INDEX idx_aeronaves_codigo ON aeronaves(codigo) WHERE deleted_at IS NULL;
CREATE INDEX idx_aeronaves_status ON aeronaves(status) WHERE deleted_at IS NULL;
CREATE INDEX idx_backups_created ON backups(created_at);
CREATE INDEX idx_importacoes_tipo ON importacoes_log(tipo);
CREATE INDEX idx_importacoes_created ON importacoes_log(created_at);
CREATE INDEX idx_simuladores_status ON simuladores(status);
CREATE INDEX idx_simuladores_deleted ON simuladores(deleted_at);
CREATE INDEX idx_treinamentos_codigo ON treinamentos(codigo);
CREATE INDEX idx_treinamentos_ativo ON treinamentos(ativo);
CREATE INDEX idx_treinamentos_deleted ON treinamentos(deleted_at);
CREATE INDEX idx_auditoria_usuario ON auditoria(usuario_id);
