CREATE TRIGGER update_papeis_updated_at
AFTER UPDATE ON papeis
FOR EACH ROW
BEGIN
  UPDATE papeis SET updated_at = datetime('now') WHERE id = OLD.id;
END;
CREATE TRIGGER update_credenciais_updated_at
AFTER UPDATE ON credenciais
FOR EACH ROW
BEGIN
  UPDATE credenciais SET updated_at = datetime('now') WHERE id = OLD.id;
END;
CREATE TRIGGER update_qt_timestamp 
AFTER UPDATE ON qualificacoes_tipos
FOR EACH ROW
BEGIN
  UPDATE qualificacoes_tipos SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE TRIGGER trg_funcionarios_update
AFTER UPDATE ON funcionarios
FOR EACH ROW
WHEN NEW.updated_at != OLD.updated_at
BEGIN
    tabela, registro_id, acao, dados_anteriores, dados_novos, origem
  ) VALUES (
    'funcionarios', NEW.id, 'UPDATE',
    json_object('nome', OLD.nome, 'email', OLD.email, 'status', OLD.status, 'cargo', OLD.cargo, 'setor', OLD.setor, 'codigo_anac', OLD.codigo_anac),
    json_object('nome', NEW.nome, 'email', NEW.email, 'status', NEW.status, 'cargo', NEW.cargo, 'setor', NEW.setor, 'codigo_anac', NEW.codigo_anac),
    'system'
  );
END;
CREATE TRIGGER trg_funcionarios_prevent_hard_delete
BEFORE DELETE ON funcionarios
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'DELETE físico proibido. Use soft delete (UPDATE deleted_at)');
END;
CREATE TRIGGER trg_audit_funcionarios_update
BEFORE UPDATE ON funcionarios
FOR EACH ROW
WHEN NEW.deleted_at IS NULL -- apenas updates não deletando
BEGIN
    tabela, registro_id, acao, origem, created_at
  ) VALUES (
    'funcionarios', OLD.id, 'UPDATE', 'trigger', datetime('now')
  );
END;
CREATE TRIGGER trg_audit_funcionarios_soft_delete_after_update
AFTER UPDATE ON funcionarios
FOR EACH ROW
WHEN NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL
BEGIN
  VALUES ('funcionarios', NEW.id, 'SOFT_DELETE', 'trigger', datetime('now'));
END;
CREATE TRIGGER trg_qualificacoes_tipos_update AFTER UPDATE ON qualificacoes_tipos FOR EACH ROW BEGIN INSERT INTO auditoria_avancada_v2 (tabela,registro_id,acao,dados_anteriores,dados_novos,origem) VALUES ('qualificacoes_tipos',NEW.id,'UPDATE',json_object('codigo',OLD.codigo,'nome',OLD.nome,'validade_meses',OLD.validade_meses),json_object('codigo',NEW.codigo,'nome',NEW.nome,'validade_meses',NEW.validade_meses),'system'); END;
CREATE TRIGGER trg_qualificacoes_tipos_prevent_hard_delete BEFORE DELETE ON qualificacoes_tipos FOR EACH ROW BEGIN SELECT RAISE(ABORT,'DELETE físico proibido em qualificacoes_tipos. Use soft delete'); END;
CREATE TRIGGER trg_qualificacoes_tipos_soft_delete AFTER UPDATE OF deleted_at ON qualificacoes_tipos FOR EACH ROW WHEN NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL BEGIN UPDATE "_backup_qh_tmp" SET deleted_at=datetime('now') WHERE qualificacao_id=NEW.id AND deleted_at IS NULL; INSERT INTO auditoria_avancada_v2 (tabela,registro_id,acao,origem) VALUES ('qualificacoes_tipos',NEW.id,'SOFT_DELETE','cascade_trigger'); END;
CREATE VIEW vw_cascade_metrics AS
SELECT 
  modelo,
  COUNT(*) as total_execucoes,
  SUM(CASE WHEN sucesso = 1 THEN 1 ELSE 0 END) as sucessos,
  SUM(CASE WHEN sucesso = 0 THEN 1 ELSE 0 END) as falhas,
  ROUND(AVG(tempo_ms), 2) as tempo_medio_ms,
  ROUND(AVG(score), 2) as score_medio,
  ROUND(100.0 * SUM(CASE WHEN sucesso = 1 THEN 1 ELSE 0 END) / COUNT(*), 2) as taxa_sucesso
FROM audit_cascade
GROUP BY modelo;
CREATE VIEW vw_cascade_recentes AS
SELECT 
  id,
  modelo,
  arquivo,
  comando,
  tempo_ms,
  sucesso,
  score,
  created_at
FROM audit_cascade
ORDER BY created_at DESC
LIMIT 50;
CREATE VIEW sessoes_simulador AS SELECT id, simulador_id, funcionario_id AS aluno_id, instrutor_id, checador_id, data AS data_sessao, hora_inicio, hora_fim, duracao_minutos, status, tipo_sessao, observacoes, created_at, updated_at, deleted_at FROM simulador_agendamentos;
CREATE VIEW fichas_simulador AS SELECT f.id, f.agendamento_slot_id AS sessao_id, f.colaborador_id_aluno AS funcionario_id, f.instrutor_id, a.data AS data_sessao, f.status, f.observacoes, f.created_at, f.updated_at, f.deleted_at FROM fichas_sessao f LEFT JOIN simulador_agendamentos a ON f.agendamento_slot_id = a.id;
CREATE VIEW qualificacoes_historico_v AS SELECT qh.id,qh.funcionario_id,qh.qualificacao_id,qh.tipo_codigo,qh.codigo,qh.categoria,qh.validade AS data_validade,qh.numero_certificado,qh.observacoes AS historico_observacoes,qh.arquivo_url,qh.created_at,qh.updated_at,CASE WHEN qh.validade IS NULL THEN 'INDETERMINADA' WHEN DATE(qh.validade) < DATE('now') THEN 'VENCIDA' WHEN DATE(qh.validade) BETWEEN DATE('now') AND DATE('now','+30 days') THEN 'PROXIMA_VENCIMENTO' WHEN DATE(qh.validade) BETWEEN DATE('now','+31 days') AND DATE('now','+60 days') THEN 'ATENCAO' ELSE 'VALIDA' END AS status_qualificacao,CASE WHEN qh.validade IS NULL THEN NULL ELSE CAST((julianday(qh.validade)-julianday('now')) AS INTEGER) END AS dias_ate_vencimento,f.nome AS funcionario_nome,f.nome_guerra AS funcionario_nome_guerra,f.email AS funcionario_email,f.matricula AS funcionario_matricula,f.cargo AS funcionario_cargo,f.funcao AS funcionario_funcao,f.setor AS funcionario_setor,f.departamento AS funcionario_departamento,f.base AS funcionario_base,f.aeronave AS funcionario_aeronave,f.escala AS funcionario_escala,COALESCE(f.status,'ATIVO') AS funcionario_status,COALESCE(f.ativo,1) AS funcionario_ativo,COALESCE(f.is_instrutor,0) AS funcionario_is_instrutor,COALESCE(f.is_checador,0) AS funcionario_is_checador,f.codigo_anac AS funcionario_codigo_anac,f.nivel_icao AS funcionario_nivel_icao,f.validade_icao AS funcionario_validade_icao,f.cma AS funcionario_cma,f.validade_cma AS funcionario_validade_cma,f.aso AS funcionario_aso,f.validade_aso AS funcionario_validade_aso,f.telefone AS funcionario_telefone,f.telefone_emergencia AS funcionario_telefone_emergencia,f.foto_url AS funcionario_foto_url,f.data_admissao AS funcionario_data_admissao,f.rg AS funcionario_rg,f.data_nascimento AS funcionario_data_nascimento,f.sexo AS funcionario_sexo,f.nacionalidade AS funcionario_nacionalidade,f.cep AS funcionario_cep,f.logradouro AS funcionario_logradouro,f.numero AS funcionario_numero,f.complemento AS funcionario_complemento,f.bairro AS funcionario_bairro,f.cidade AS funcionario_cidade,f.estado AS funcionario_estado,f.sispat AS funcionario_sispat,f.prestserv AS funcionario_prestserv,f.contato_emergencia_nome AS funcionario_contato_emergencia,f.observacoes AS funcionario_observacoes,COALESCE(qt.codigo,qh.tipo_codigo,qh.codigo) AS qualificacao_codigo,COALESCE(qt.nome,qh.tipo_codigo,qh.codigo) AS qualificacao_nome,qt.descricao AS qualificacao_descricao,COALESCE(qt.categoria,qh.categoria) AS qualificacao_categoria,qt.validade_meses AS qualificacao_validade_meses,NULL AS data_conclusao,NULL AS nota,NULL AS instrutor,NULL AS local_treinamento,NULL AS carga_horaria,NULL AS modalidade FROM qualificacoes_historico qh LEFT JOIN funcionarios f ON qh.funcionario_id = f.id AND f.deleted_at IS NULL LEFT JOIN qualificacoes_tipos qt ON qh.qualificacao_id = qt.id AND qt.deleted_at IS NULL WHERE qh.deleted_at IS NULL;
