INSERT INTO "certificados_templates" VALUES(1,1,'Template Padrão Aviação','Template padrão para certificados de treinamento em aviação','TREINAMENTO',replace('{\n    "version": "1.0",\n    "layout": {\n      "orientation": "landscape",\n      "size": "A4",\n      "margin": 50\n    },\n    "elements": [\n      {\n        "type": "logo",\n        "position": {"x": 50, "y": 50},\n        "size": {"width": 120, "height": 60},\n        "source": "template_logo_url"\n      },\n      {\n        "type": "title",\n        "text": "CERTIFICADO DE CONCLUSÃO",\n        "position": {"x": "center", "y": 100},\n        "style": {\n          "fontSize": 24,\n          "fontWeight": "bold",\n          "color": "primary"\n        }\n      },\n      {\n        "type": "subtitle",\n        "text": "Certificamos que",\n        "position": {"x": "center", "y": 170},\n        "style": {\n          "fontSize": 14,\n          "color": "secondary"\n        }\n      },\n      {\n        "type": "field",\n        "name": "pessoa_nome",\n        "position": {"x": "center", "y": 200},\n        "style": {\n          "fontSize": 20,\n          "fontWeight": "bold",\n          "color": "highlight",\n          "uppercase": true\n        }\n      },\n      {\n        "type": "text",\n        "text": "concluiu com sucesso o treinamento",\n        "position": {"x": "center", "y": 240},\n        "style": {\n          "fontSize": 14,\n          "color": "secondary"\n        }\n      },\n      {\n        "type": "field",\n        "name": "qualificacao_nome",\n        "position": {"x": "center", "y": 270},\n        "style": {\n          "fontSize": 18,\n          "fontWeight": "bold",\n          "color": "primary"\n        }\n      },\n      {\n        "type": "footer",\n        "position": {"x": 50, "y": 500},\n        "elements": [\n          {\n            "type": "text",\n            "text": "Matrícula: {matricula}",\n            "style": {"fontSize": 10}\n          },\n          {\n            "type": "text",\n            "text": "Código Qualificação: {qualificacao_codigo}",\n            "style": {"fontSize": 10}\n          },\n          {\n            "type": "text",\n            "text": "Data de Conclusão: {data_realizacao}",\n            "style": {"fontSize": 10}\n          },\n          {\n            "type": "text",\n            "text": "Validade: {data_validade}",\n            "style": {"fontSize": 10}\n          }\n        ]\n      },\n      {\n        "type": "signature",\n        "position": {"x": 650, "y": 480},\n        "source": "template_assinatura_url",\n        "label": "Responsável Técnico"\n      }\n    ]\n  }','\n',char(10)),NULL,NULL,NULL,'Arial',24,14,'#003366','#666666','#0066CC','landscape','A4',2,1,1,'1.0',NULL,NULL,'2025-11-08 12:44:55',NULL,'2025-11-08 12:44:55',NULL);
